import json

with open('data/debugbench_with_tests.jsonl') as f:
    generated = [json.loads(l) for l in f]
with open('data/debugbench_validated.jsonl') as f:
    valid_slugs = {json.loads(l)['slug'] for l in f}

# Solution failed samples
import subprocess, tempfile, re
from pathlib import Path

TYPING_IMPORTS = '''from typing import List, Optional, Dict, Tuple, Set
from collections import defaultdict, Counter, deque
'''

def clean_test_code(test_code):
    code = re.sub(r'^\`\`\`(?:python)?\s*\n?', '', test_code.strip())
    code = re.sub(r'\n?\`\`\`\s*$', '', code)
    code = re.sub(r'^\s*from solution import Solution\s*$', '', code, flags=re.MULTILINE)
    code = re.sub(r'^\s*import solution\s*$', '', code, flags=re.MULTILINE)
    lines = code.split('\n')
    result = []
    in_solution = False
    for line in lines:
        stripped = line.strip()
        if not in_solution:
            if stripped.startswith('class Solution:') or stripped.startswith('class Solution('):
                in_solution = True
                continue
            result.append(line)
        else:
            if stripped == '' or line[0] in (' ', '\t'):
                continue
            in_solution = False
            result.append(line)
    return '\n'.join(result)

fail_reasons = {'assertion_error': 0, 'import_error': 0, 'type_error': 0, 'name_error': 0, 'syntax_error': 0, 'timeout': 0, 'other': 0, 'buggy_passed': 0}
sol_fail_count = 0

for s in generated:
    if s['slug'] in valid_slugs:
        continue

    cleaned = clean_test_code(s['test_code'])
    combined = TYPING_IMPORTS + '\n' + s['solution'] + '\n\n' + cleaned

    with tempfile.NamedTemporaryFile(mode='w', suffix='.py', delete=False, prefix='dbtest_') as f:
        f.write(combined)
        tmp = f.name

    try:
        result = subprocess.run(['python', '-m', 'pytest', tmp, '-x', '-q', '--tb=short', '--no-header'], capture_output=True, text=True, timeout=10)
        output = result.stdout + result.stderr
        if result.returncode != 0:
            sol_fail_count += 1
            if 'AssertionError' in output or 'assert ' in output:
                fail_reasons['assertion_error'] += 1
            elif 'ImportError' in output or 'ModuleNotFoundError' in output:
                fail_reasons['import_error'] += 1
            elif 'TypeError' in output:
                fail_reasons['type_error'] += 1
            elif 'NameError' in output:
                fail_reasons['name_error'] += 1
            elif 'SyntaxError' in output:
                fail_reasons['syntax_error'] += 1
            else:
                fail_reasons['other'] += 1
        else:
            # solution passed but buggy also passed
            fail_reasons['buggy_passed'] += 1
    except subprocess.TimeoutExpired:
        sol_fail_count += 1
        fail_reasons['timeout'] += 1
    finally:
        Path(tmp).unlink(missing_ok=True)

print(f'Failed samples: {len(generated) - len(valid_slugs)}')
print(f'  Solution failed: {sol_fail_count}')
print(f'  Buggy also passed: {fail_reasons[\"buggy_passed\"]}')
print(f'\nSolution failure breakdown:')
for k, v in sorted(fail_reasons.items(), key=lambda x: -x[1]):
    if k != 'buggy_passed' and v > 0:
        print(f'  {k}: {v}')
